// Before: new function reference on every render
function Parent() {
  const [text, setText] = useState('');
  return <Child onChange={setText} />;
}

// After: stable reference with useCallback
function Parent() {
  const [text, setText] = useState('');
  const handleChange = useCallback((value) => setText(value), []);
  return <Child onChange={handleChange} />;
}
